    public function run(): void
    {
        /*
         * Large JSON columns are written in separate compact updates.
         * This follows the reference V2/V3 format and lowers the risk of
         * "MySQL server has gone away" errors on local XAMPP installations.
         */
        $now = now();

        DB::table('module_library_items')->updateOrInsert(
            ['module_code' => 'DATABASE-MANAGEMENT-DATA-SCIENCE-BASIC-V3'],
            [
                'module_no' => 10,
                'title' => 'Database Management for Data Science',
                'year_level' => 'Year 2',
                'version_no' => 3,
                'version_name' => 'Database Management for Data Science Applied Problem Solving',
                'version_code' => 'V3',
                'description' => 'Relational databases, SQL querying, NoSQL systems, data pipelines, and schema design for analytics workloads. This version emphasizes applied scenarios, design decisions, validation, integration, project readiness, and defensible technical communication.',
                'estimated_minutes' => 800,
                'sort_order' => 30,
                'is_active' => true,
                'created_at' => $now,
                'updated_at' => $now,
            ]
        );

        DB::table('module_library_items')
            ->where('module_code', 'DATABASE-MANAGEMENT-DATA-SCIENCE-BASIC-V3')
            ->update([
                'content_sections' => json_encode($this->contentSections(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);

        DB::table('module_library_items')
            ->where('module_code', 'DATABASE-MANAGEMENT-DATA-SCIENCE-BASIC-V3')
            ->update([
                'mcq_questions' => json_encode($this->mcqQuestions(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);
    }

